function CommercialMarker({ findings, label, locationKey = label, openLocationKey, onOpenLocationChange }: { findings: CommercialValidationFinding[]; label: string; locationKey?: string; openLocationKey?: string | null; onOpenLocationChange?: (key: string | null) => void }) {
  const warnings = findings.filter((finding) => finding.severity === "warning").length;
  const markerRef = useRef<HTMLSpanElement>(null);
  const [localOpenLocationKey, setLocalOpenLocationKey] = useState<string | null>(null);
  const activeLocationKey = openLocationKey ?? localOpenLocationKey;
  const setActiveLocationKey = onOpenLocationChange ?? setLocalOpenLocationKey;
  const open = activeLocationKey === locationKey;
  const [position, setPosition] = useState({ left: 16, top: 16 });
  const updatePosition = () => { const rect = markerRef.current?.getBoundingClientRect(); if (!rect) return; const width = Math.min(288, window.innerWidth - 32); const left = Math.max(16, Math.min(rect.left, window.innerWidth - width - 16)); const below = rect.bottom + 8; setPosition({ left, top: below + 220 > window.innerHeight ? Math.max(16, rect.top - 8) : below }); };
  useEffect(() => { if (!open) return; updatePosition(); const outside = (event: PointerEvent) => { if (!markerRef.current?.contains(event.target as Node)) setActiveLocationKey(null); }; const escape = (event: KeyboardEvent) => { if (event.key === "Escape") setActiveLocationKey(null); }; const scroll = () => setActiveLocationKey(null); const anotherMarker = (event: Event) => { if ((event as CustomEvent<string>).detail !== locationKey) setActiveLocationKey(null); }; document.addEventListener("pointerdown", outside); document.addEventListener("keydown", escape); document.addEventListener("scroll", scroll, true); document.addEventListener("commercial-validation-marker-open", anotherMarker); return () => { document.removeEventListener("pointerdown", outside); document.removeEventListener("keydown", escape); document.removeEventListener("scroll", scroll, true); document.removeEventListener("commercial-validation-marker-open", anotherMarker); }; }, [open, locationKey, setActiveLocationKey]);
  if (!findings.length) return null;
  return <span ref={markerRef} className="inline-block align-middle"><button type="button" aria-expanded={open} aria-label={`${findings.length} commercial validation finding${findings.length === 1 ? "" : "s"} for ${label}`} onClick={() => { if (open) setActiveLocationKey(null); else { updatePosition(); document.dispatchEvent(new CustomEvent("commercial-validation-marker-open", { detail: locationKey })); setActiveLocationKey(locationKey); } }} className={`ml-1 inline-flex items-center rounded px-1 text-xs font-bold ${warnings ? "bg-amber-100 text-amber-800" : "bg-sky-100 text-sky-800"}`}>{warnings ? "[warning]" : "[info]"}{findings.length > 1 ? ` ${findings.length}` : ""}</button>{open ? <span role="dialog" aria-label={`Commercial validation details for ${label}`} style={{ left: position.left, top: position.top }} className="fixed z-40 max-h-[calc(100vh-4rem)] w-72 max-w-[calc(100vw-2rem)] overflow-y-auto rounded border border-zinc-200 bg-white p-3 text-xs text-zinc-800 shadow-lg"><p className="break-words font-semibold">{label}</p>{findings.map((finding, index) => <span key={`${finding.code}-${index}`} className="mt-2 block border-t border-zinc-100 pt-2 first:mt-1"><span className="block break-words font-semibold">{finding.title}</span><span className="mt-1 block break-words whitespace-normal">{finding.message}</span><span className="mt-1 block break-words whitespace-normal text-zinc-600">{commercialValidationActionLabel(finding)}</span></span>)}</span> : null}</span>;
}

